#!/bin/sh
# Builds on the Mac VM (ssh 2229) and installs on the FreeBSD VM (ssh 2222) the open AppKit + a test program: sh open/deploy.sh [program.m]
R="$(cd "$(dirname "$0")/.." && pwd)"; T="${CLAUDE_JOB_DIR:-/tmp}/tmp"; mkdir -p "$T"; P="${1:-hello}"
MK="-i $HOME/fbsd-vm/id_ed25519 -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o IdentitiesOnly=yes -o BatchMode=yes"; K="-i $HOME/fbsd-vm/id_ed25519 -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -q -o ConnectTimeout=10"
tar czf $T/wsb.tgz -C "$R" include src/client.c src/compositor_sw.c src/region.c src/ipc.c src/evrec.c src/buffer.c appkit/decompiled/src appkit/decompiled/test/stubs.m open
scp -P 2229 $MK $T/wsb.tgz alex@localhost:/tmp/ >/dev/null 2>&1
ssh -p 2229 $MK alex@localhost "rm -rf /tmp/wsb && mkdir /tmp/wsb && cd /tmp/wsb && tar xzf ../wsb.tgz && sh open/build-appkit.sh /tmp/wsb/out 2>&1 | grep -i 'error\|FAILED' ; if [ $P != hello -a $P != textsys ]; then cc -arch x86_64 -fobjc-arc -Wno-everything -o out/$P open/$P.m -framework Cocoa 2>&1 | head -5; else cc -arch x86_64 -fobjc-arc -Wno-everything -Iappkit/decompiled/src -o out/$P open/$P.m out/AppKit -Wl,-undefined,dynamic_lookup -framework Foundation -framework CoreGraphics -framework CoreText 2>&1 | head -5; fi; cd out && tar czf ../outk.tgz AppKit Cocoa stub-* $P" 2>&1 | grep -v Warn
scp -P 2229 $MK alex@localhost:/tmp/wsb/outk.tgz $T/ >/dev/null 2>&1; if [ $P != hello -a $P != textsys ]; then rm -rf $T/pk && mkdir $T/pk && tar xzf $T/outk.tgz -C $T/pk && python3 "$R/open/open-patch.py" $T/pk/$P $T/pk/$P.p && mv $T/pk/$P.p $T/pk/$P && chmod +x $T/pk/$P && tar czf $T/outk.tgz -C $T/pk .; fi; scp -P 2222 $K $T/outk.tgz root@localhost:/tmp/ >/dev/null
ssh -p 2222 $K root@localhost "mkdir -p /open /tmp/ohello && tar xzf /tmp/outk.tgz -C /tmp/ohello && cp /tmp/ohello/AppKit /tmp/ohello/Cocoa /tmp/ohello/stub-* /open/ 2>/dev/null; cp /tmp/ohello/AppKit /tmp/ohello/Cocoa /open/ && chmod +x /tmp/ohello/$P && pkill -9 -x $P; pgrep -x wsd >/dev/null || { rm -f /tmp/wsd.sock; (/root/misc-iso/wsbsd/wsd -t -s /tmp/wsd.sock >/tmp/wsd.log 2>&1 &); sleep 2; }; (OPEN_DEBUG=1 WS_SOCKET=/tmp/wsd.sock /tmp/ohello/$P >/tmp/$P.out 2>&1 &); sleep 8; head -5 /tmp/$P.out | cut -c1-200; cd /tmp; WS_SOCKET=/tmp/wsd.sock /root/misc-iso/wsbsd/wsshot /tmp/shot.ppm"
scp -P 2222 $K root@localhost:/tmp/shot.ppm $T/shot.ppm >/dev/null; python3 "$R/tools/ppm2png.py" $T/shot.ppm $T/shot.png
